'''

--- Day 1: Inverse Captcha ---


'''


t1 = '1122'
t2 = '1111'
t3 = '1234'
t4 = '91212129'
tpuzzle = ''''''

def check_pattern(_input, look_ahead=1):
    nums = []

    l = len(_input)
    for index in range(l):
        if _input[index] == _input[(index+look_ahead)%l]:
            nums.append(int(_input[index]))

    return nums




def solve(_input):
    pattern = check_pattern(_input)
    acc = 0 

    for n in pattern:
        acc += n
    print(f'solution: {_input} \nsolution -> ', acc, '\n')
    return acc

def solve2(_input):
    pattern = check_pattern(_input, look_ahead=(int(len(_input)/2)))
    acc = 0 

    print(pattern)
    for n in pattern:
        acc += n

    print(f'solution: {_input} \nsolution -> ', acc, '\n')
    return acc



solve(t1)
solve(t2)
solve(t3)
solve(t4)
solve(tpuzzle)

solve2('123123')
solve2('12131415')
solve2('1122')
solve2(tpuzzle)

